import { CanvasTexture, NearestFilter, SRGBColorSpace, type Texture } from "three";
import { DIRECTIONS, SHEET_COLUMNS, SPRITE_H_PX, SPRITE_W_PX } from "./billboard";
import { TILE_PX, type AtlasLayout } from "./tileChunk";
import { hash2 } from "./world";

/**
 * Placeholder art generated by code (no downloads, D-029/D-153): 32 px coloured squares with a
 * 1 px outline and a little deterministic pixel noise. Declared in LICENSES.md.
 */
export const ATLAS: AtlasLayout = { columns: 4, rows: 4 };

/** Pixel-art texture contract (D-154): nearest in both directions, no mipmaps, sRGB. */
export function configurePixelTexture<T extends Texture>(tex: T): T {
  tex.magFilter = NearestFilter;
  tex.minFilter = NearestFilter;
  tex.generateMipmaps = false;
  tex.colorSpace = SRGBColorSpace;
  tex.anisotropy = 1;
  tex.needsUpdate = true;
  return tex;
}

function canvas(w: number, h: number): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const ctx = c.getContext("2d");
  if (!ctx) throw new Error("2D canvas not available");
  ctx.imageSmoothingEnabled = false;
  return [c, ctx];
}

interface CellArt {
  fill?: string;
  outline?: string;
  noise?: string;
  draw?: (ctx: CanvasRenderingContext2D, x: number, y: number) => void;
}

const px = (ctx: CanvasRenderingContext2D, color: string, x: number, y: number, w = 1, h = 1) => {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
};

/** Index = atlas cell (tile id - 1). Cells 0-6 ground, 8-11 details (transparent). */
const CELLS: Record<number, CellArt> = {
  0: { fill: "#6fa44c", outline: "#5c8f3e", noise: "#7db458" }, // grass
  1: { fill: "#5e9442", outline: "#4d7f35", noise: "#6aa24c" }, // grass dark
  2: { fill: "#c8a36a", outline: "#b08c56", noise: "#d6b47c" }, // dirt path
  3: { fill: "#7a5638", outline: "#674630", noise: "#87613f" }, // tilled soil
  4: { fill: "#3f7fbf", outline: "#356ea6", noise: "#5a98d0" }, // water
  5: { fill: "#a9a69c", outline: "#8c8981", noise: "#bab7ad" }, // stone (El Cruce)
  6: { fill: "#e0cf96", outline: "#c9b880", noise: "#ecdcaa" }, // sand
  8: {
    draw: (ctx, x, y) => {
      for (const [dx, dy, c] of [[10, 12, "#f2e15c"], [20, 18, "#f07c9a"], [14, 22, "#ffffff"]] as const) {
        px(ctx, "#2f5a26", x + dx, y + dy + 2, 1, 4);
        px(ctx, c, x + dx - 1, y + dy - 1, 3, 3);
      }
    },
  },
  9: {
    draw: (ctx, x, y) => {
      for (let i = 0; i < 5; i++) px(ctx, "#4c8a34", x + 11 + i * 2, y + 14 - (i % 2) * 3, 1, 6 + (i % 2) * 3);
    },
  },
  10: {
    draw: (ctx, x, y) => {
      px(ctx, "#5b5b5b", x + 11, y + 15, 10, 7);
      px(ctx, "#8d8d8d", x + 12, y + 15, 7, 4);
      px(ctx, "#2f2f2f", x + 11, y + 22, 10, 1);
    },
  },
  11: {
    draw: (ctx, x, y) => {
      for (let i = 0; i < 4; i++) {
        px(ctx, "#5fae3f", x + 4 + i * 8, y + 12, 2, 6);
        px(ctx, "#8fd06a", x + 3 + i * 8, y + 11, 4, 2);
      }
    },
  },
};

export function drawTileAtlas(): HTMLCanvasElement {
  const [c, ctx] = canvas(ATLAS.columns * TILE_PX, ATLAS.rows * TILE_PX);
  for (const [key, art] of Object.entries(CELLS)) {
    const cell = Number(key);
    const x = (cell % ATLAS.columns) * TILE_PX;
    const y = Math.floor(cell / ATLAS.columns) * TILE_PX;
    if (art.fill) px(ctx, art.fill, x, y, TILE_PX, TILE_PX);
    if (art.noise) {
      for (let i = 0; i < TILE_PX; i++) {
        for (let j = 0; j < TILE_PX; j++) if (hash2(i + cell * 97, j) < 0.08) px(ctx, art.noise, x + i, y + j);
      }
    }
    if (art.outline) {
      ctx.strokeStyle = art.outline;
      ctx.lineWidth = 1;
      ctx.strokeRect(x + 0.5, y + 0.5, TILE_PX - 1, TILE_PX - 1);
    }
    art.draw?.(ctx, x, y);
  }
  return c;
}

export interface Palette {
  readonly shirt: string;
  readonly pants: string;
  readonly hair: string;
  readonly skin: string;
}

export const PALETTES: readonly Palette[] = [
  { shirt: "#d04a3a", pants: "#3a4a7a", hair: "#3a2a1a", skin: "#e8b88a" },
  { shirt: "#3a8ad0", pants: "#4a3a2a", hair: "#d8b04a", skin: "#f0c8a0" },
  { shirt: "#4ab05a", pants: "#2a2a3a", hair: "#1a1a1a", skin: "#a87050" },
  { shirt: "#e0b03a", pants: "#5a3a5a", hair: "#8a3a1a", skin: "#e8b88a" },
  { shirt: "#9a5ad0", pants: "#3a5a3a", hair: "#5a4a3a", skin: "#c89068" },
  { shirt: "#e07ab0", pants: "#2a3a5a", hair: "#2a1a0a", skin: "#f0c8a0" },
  { shirt: "#5ad0c8", pants: "#5a4a2a", hair: "#c8c8c8", skin: "#d8a078" },
  { shirt: "#f08a3a", pants: "#3a3a3a", hair: "#4a2a1a", skin: "#8a5a3a" },
];

/** 4x4 sheet (rows down/left/right/up, cols idle + 3 walk frames) of 32x48 cells. */
export function drawSpriteSheet(p: Palette): HTMLCanvasElement {
  const [c, ctx] = canvas(SHEET_COLUMNS * SPRITE_W_PX, DIRECTIONS.length * SPRITE_H_PX);
  const outline = "#1a1a22";
  DIRECTIONS.forEach((dir, row) => {
    for (let col = 0; col < SHEET_COLUMNS; col++) {
      const x = col * SPRITE_W_PX;
      const y = row * SPRITE_H_PX;
      const step = col === 0 ? 0 : col === 2 ? 0 : col === 1 ? 2 : -2;
      const bob = col === 2 ? 1 : 0;
      // legs (feet on the bottom row of the cell: feet-anchored)
      px(ctx, outline, x + 10, y + 34 + bob, 12, 14 - bob);
      px(ctx, p.pants, x + 11, y + 35 + bob, 4, 12 - bob + (step > 0 ? -1 : 0));
      px(ctx, p.pants, x + 17, y + 35 + bob, 4, 12 - bob + (step < 0 ? -1 : 0));
      // body
      px(ctx, outline, x + 8, y + 20 + bob, 16, 16);
      px(ctx, p.shirt, x + 9, y + 21 + bob, 14, 14);
      // head
      px(ctx, outline, x + 9, y + 5 + bob, 14, 16);
      px(ctx, p.skin, x + 10, y + 6 + bob, 12, 14);
      px(ctx, p.hair, x + 10, y + 6 + bob, 12, dir === "up" ? 14 : 5);
      if (dir === "down") {
        px(ctx, outline, x + 12, y + 13 + bob, 2, 2);
        px(ctx, outline, x + 18, y + 13 + bob, 2, 2);
      } else if (dir === "left") {
        px(ctx, outline, x + 11, y + 13 + bob, 2, 2);
        px(ctx, p.hair, x + 18, y + 6 + bob, 4, 10);
      } else if (dir === "right") {
        px(ctx, outline, x + 19, y + 13 + bob, 2, 2);
        px(ctx, p.hair, x + 10, y + 6 + bob, 4, 10);
      }
    }
  });
  return c;
}

/** Soft round blob for the sprite shadow (all tiers, D-154). */
export function drawBlobShadow(): HTMLCanvasElement {
  const [c, ctx] = canvas(32, 32);
  const g = ctx.createRadialGradient(16, 16, 2, 16, 16, 15);
  g.addColorStop(0, "rgba(0,0,0,0.55)");
  g.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 32, 32);
  return c;
}

export function pixelCanvasTexture(c: HTMLCanvasElement): CanvasTexture {
  return configurePixelTexture(new CanvasTexture(c));
}

/** Uncompressed GPU bytes of an RGBA8 texture without mipmaps. */
export const textureGpuBytes = (c: { width: number; height: number }) => c.width * c.height * 4;
